mapper.select:
SELECT * FROM (SELECT rownum as rnum, a.* FROM (SELECT sc.studycafe_idx, sc.studycafe_name, sc.studycafe_addr, sc.studycafe_lat, sc.studycafe_lng, SUM(CASE WHEN s.seat_status != 'RESERVED' THEN 1 ELSE 0 END) as "avaliable", COUNT(*) AS "all" FROM studycafe sc JOIN seat s ON sc.studycafe_idx = s.studycafe_idx GROUP BY (sc.studycafe_idx, sc.studycafe_name, sc.studycafe_addr, sc.studycafe_lat, sc.studycafe_lng))a)b
WHERE rnum >= #{start} and rnum <= #{end} and studycafe_addr LIKE '%'||#{region}||'%'
WHERE rnum >= #{start} and rnum <= #{end}

select ticket_category_idx, ticket_category_name, studycafe_idx
from ticket_category
where studycafe_idx = #{studycafe_idx}
